package main

import "sync"

type Store struct {
	mu sync.Mutex
	m  map[string]string
}

func NewStore() *Store { return &Store{m: map[string]string{}} }

func (s *Store) Put(k, v string) { s.mu.Lock(); defer s.mu.Unlock(); s.m[k] = v }

func (s *Store) Get(k string) (string, bool) { s.mu.Lock(); defer s.mu.Unlock(); v, ok := s.m[k]; return v, ok }

